package org.acme.mail;

public class Template {
    public String escape(String s) {
        return s.replace("<", "&lt;").replace(">", "&gt;");
    }

    public String render(String s, String locale) {
        return "ar".equals(locale) ? "\u202B" + s : s;
    }
}

package org.acme.mail;

import org.junit.jupiter.api.Disabled;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;

class TemplateTest {
    @Disabled("RTL fonts are not installed on CI agents")
    @Test
    void rendersRtlLocale() {
        assertEquals("\u202Bhi", new Template().render("hi", "ar"));
    }

    @Test
    void escapesHtmlEntities() {
        assertEquals("&lt;b&gt;", new Template().escape("<b>"));
    }
}

